See: https://blog.csdn.net/wy313622821/article/details/105047034
```
// Send a event
ChatUIKitFlowBus.with<ChatUIKitEvent>(ChatUIKitEvent.EVENT.UPDATE.name).post(lifecycleScope,
ChatUIKitEvent(ChatUIKitEvent.EVENT.UPDATE.name, ChatUIKitEvent.TYPE.MESSAGE))
// Receive a event
ChatUIKitFlowBus.with<ChatUIKitEvent>(ChatUIKitEvent.EVENT.UPDATE.name).register(this) {
if (it.isMessageChange) {
// update message
}
}
```
Also, you can send a stick event, such as:
```
// Send a stick event
ChatUIKitFlowBus.withStick<ChatUIKitEvent>(ChatUIKitEvent.EVENT.UPDATE.name).post(lifecycleScope,
ChatUIKitEvent(ChatUIKitEvent.EVENT.UPDATE.name, ChatUIKitEvent.TYPE.MESSAGE))
// Receive a stick event
ChatUIKitFlowBus.withStick<ChatUIKitEvent>(ChatUIKitEvent.EVENT.UPDATE.name).register(this) {
if (it.isMessageChange) {
// update message
}
}
// Receive a stick event with lifecycle
ChatUIKitFlowBus.withStick<ChatUIKitEvent>(ChatUIKitEvent.EVENT.UPDATE.name)
.onLifeCycle(Lifecycle.State.RESUMED).register(this) {
if (it.isMessageChange) {
// update message
}
}
```

